const raw = $json.content?.[0]?.text || '{}';
let resumen; try { resumen = JSON.parse(raw); } catch(e) { resumen = { titulo: 'Accion pendiente', que_se_hara: raw, impacto_esperado: 'Revisar manualmente', que_no_se_puede_deshacer: 'Desconocido', recomendacion: 'aprobar' }; }
return [{ json: {
  resumen,
  responsable: $('Config').item.json.responsable_email,
  accion: $('Config').item.json.accion_descripcion,
  timestamp: new Date().toISOString()
} }];

const decision = $json.body || $json;
const accion = decision.accion || 'rechazar';
const motivo = decision.motivo || '';
return [{ json: { accion, motivo, timestamp_decision: new Date().toISOString() } }];
